sql.if:
AND EXISTS (
        SELECT ctgry_id
          FROM dtmeta.tb_meta_category  a1  
         WHERE a1.ctgry_id         = #{ctgryId} 
           AND (   ( t3.medata_val = a1.ctgry_id           AND t6.data_type_mtcd = 'categoryId' )
                OR ( t3.medata_val = a1.ctgry_rdf_cncpt_nm AND t6.data_type_mtcd = 'categoryConcept' )
               )
    )

mapper.select:
SELECT /* SQL_ID: MetadataMapper.selectMetadataSimpleListBySetId */ t3.medata_id , t3.medata_set_id , t3.prpty_id , t3.val_model_id , t3.model_prpty_id , t3.lang_mtcd , t3.medata_val , dtmeta.ST_AsGeoJson(t3.geodata_val) AS geodata_val FROM dtmeta.tb_meta_dataset t1 INNER JOIN dtmeta.tb_meta_data t3 ON t1.medata_set_id = t3.medata_set_id LEFT OUTER JOIN dtmeta.tb_meta_property t5 ON t3.prpty_id = t5.prpty_id LEFT OUTER JOIN dtmeta.tb_meta_model t6 ON t3.val_model_id = t6.model_id LEFT OUTER JOIN dtmeta.tb_meta_modelproperty t7 ON t3.model_prpty_id = t7.model_prpty_id LEFT OUTER JOIN dtmeta.tb_portal_code c3 ON t6.data_type_mtcd = c3.mtcd AND c3.mtcd_grp_id = 'MCG00013' WHERE t1.medata_set_id = #{medataSetId}
AND c3.mtcd IS NOT NULL
AND c3.mtcd IS NULL
AND t5.cnt_prpty_yn = #{cntPrptyYn}
ORDER BY t7.model_prpty_sort_odrg

SELECT /* SQL_ID: MetadataMapper.selectMetadataListForSave */ m1.model_prpty_id , m1.prpty_id , m1.prpty_nm , m1.prpty_logic_nm , m1.data_array_yn , m1.prpty_scrn_indc_yn , m1.model_prpty_mand_mtcd , m1.model_prpty_mand_mtcd_nm , m1.model_prpty_val_exam , m1.set_usg_prpty_yn , CASE WHEN m1.model_prpty_mand_mtcd = 'readonly' OR m1.set_usg_prpty_yn = 'Y' THEN 'N' ELSE 'Y' END AS editable_yn , m1.lang_enable_yn , m1.data_type_mtcd , m1.range_mtcd_grp_id , m1.val_model_id , m1.val_model_nm , m1.val_model_logic_nm , m1.val_model_type_mtcd , #{medataSetId} AS medata_set_id , m2.medata_id , COALESCE(m2.lang_mtcd, m1.lang_mtcd) AS lang_mtcd , m2.medata_val , m2.medata_val_nm , CASE WHEN m1.val_model_type_mtcd = 'object_type' THEN #{resourceUrl} || m2.medata_val ELSE NULL END AS url FROM ( SELECT ROW_NUMBER() OVER(ORDER BY t1.model_prpty_sort_odrg, t2.prpty_sort_odrg) AS sort_odrg , t1.model_prpty_id , t1.prpty_id , t2.prpty_nm , t2.prpty_logic_nm , t2.data_array_yn , t2.prpty_scrn_indc_yn , t1.model_prpty_mand_mtcd , c1.mtcd_nm AS model_prpty_mand_mtcd_nm , t3.range_model_id AS val_model_id , t4.model_nm AS val_model_nm , t4.model_logic_nm AS val_model_logic_nm , t4.model_type_mtcd AS val_model_type_mtcd , t1.model_prpty_val_exam , t4.use_lang_mtcd AS lang_mtcd , t4.data_type_mtcd AS data_type_mtcd , t3.range_mtcd_grp_id , CASE WHEN t4.data_type_mtcd = 'langString' THEN 'Y' ELSE 'N' END AS lang_enable_yn , CASE WHEN c2.mtcd IS NOT NULL THEN 'Y' ELSE 'N' END AS set_usg_prpty_yn FROM dtmeta.tb_meta_modelproperty t1 LEFT OUTER JOIN dtmeta.tb_meta_property t2 ON t1.prpty_id = t2.prpty_id AND t2.prpty_data_sttus_mtcd = 'use' LEFT OUTER JOIN dtmeta.tb_meta_propertydefine t3 ON t1.prpty_id = t3.prpty_id AND t3.prpty_def_chg_yn = 'N' LEFT OUTER JOIN dtmeta.tb_meta_model t4 ON t3.range_model_id = t4.model_id LEFT OUTER JOIN dtmeta.tb_portal_code c1 ON t1.model_prpty_mand_mtcd = c1.mtcd AND c1.mtcd_grp_id = 'MCG00004' LEFT OUTER JOIN dtmeta.tb_portal_code c2 ON t4.data_type_mtcd = c2.mtcd AND c2.mtcd_grp_id = 'MCG00013' WHERE t1.model_id = #{modelId} AND t1.model_prpty_del_yn = 'N' AND t2.data_array_yn = 'N' AND ( t4.model_type_mtcd = 'object_type' OR t4.data_type_mtcd NOT IN ( 'json', 'geoJson' ) )
AND t2.cnt_prpty_yn = #{cntPrptyYn}
) m1 LEFT OUTER JOIN ( SELECT d1.medata_id , d1.lang_mtcd , d1.medata_val , d1.model_prpty_id , d3.medata_set_nm AS medata_val_nm FROM dtmeta.tb_meta_data d1 LEFT OUTER JOIN dtmeta.tb_meta_property d2 ON d1.prpty_id = d2.prpty_id LEFT OUTER JOIN dtmeta.tb_meta_dataset d3 ON d1.medata_val = d3.medata_set_id WHERE d1.medata_set_id = #{medataSetId} AND d2.data_array_yn = 'N' ) m2 ON m1.model_prpty_id = m2.model_prpty_id ORDER BY m1.sort_odrg

mapper.insert:

	        SELECT CONCAT('D', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_meta_data') AS varchar), 6, '0')) 

		INSERT /* SQL_ID: MetadataMapper.insertMetadataAutoKey */
		       INTO dtmeta.tb_meta_data
			 ( medata_id
             , medata_set_id
             , prpty_id
             , val_model_id
             , model_prpty_id
             , lang_mtcd
             , medata_val

             , geodata_val

			 ) VALUES 
			 ( 
			   #{medataId}			 			 
			 , #{medataSetId}
			 , #{prptyId}
			 , #{valModelId}
			 , #{modelPrptyId}
			 , #{langMtcd}
			 , #{medataVal}

			 , dtmeta.ST_GeomFromGeoJSON(#{geodataVal})	

			 )

mapper.update:
		UPDATE /* SQL_ID: MetadataMapper.updateMetadata */
               dtmeta.tb_meta_data
		   SET val_model_id             = #{valModelId}
		     , lang_mtcd                = #{langMtcd}
		     , medata_val               = #{medataVal}

             , geodata_val		        = dtmeta.ST_GeomFromGeoJSON(#{geodataVal}) 


             , geodata_val              = null

		 WHERE medata_id          = #{medataId}

mapper.delete:
DELETE /* SQL_ID: MetadataMapper.deleteMetadata */
  FROM dtmeta.tb_meta_data
 WHERE medata_id          = #{medataId}

DELETE /* SQL_ID: MetadataMapper.deleteMetadataAllBySetId */
  FROM dtmeta.tb_meta_data
 WHERE medata_set_id      = #{medataSetId}

DELETE /* SQL_ID: MetadataMapper.deleteMetadataAllByPropertyId */
  FROM dtmeta.tb_meta_data
 WHERE medata_set_id      = #{medataSetId}
   AND prpty_id           = #{prptyId}

   AND medata_val IN  #{item} 


   AND 
       ( medata_val = #{item.medataVal} AND lang_mtcd = #{item.langMtcd} )

        DELETE /* SQL_ID: MetadataMapper.deleteMetadataAllByRefPropertyId */
	      FROM dtmeta.tb_meta_data
         WHERE medata_set_id      = #{medataSetId}
           AND prpty_id           = ( SELECT prpty_id 
                                        FROM dtmeta.tb_meta_propertydefine 
                                       WHERE ref_prpty_id     = #{prptyId}
                                         AND prpty_def_chg_yn = 'N'
                                    )
